const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfo(obj) {
    return new Promise((resolve, reject) => {
      obj.getInfo((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });
  }
  try {
    // 1. Geometry & Time Definitions
    const centralOK = ee.Geometry.Polygon([[[-98.5, 36.2], [-98.5, 34.7], [-96.5, 34.7], [-96.5, 36.2], [-98.5, 36.2]]]);
    const northTX   = ee.Geometry.Polygon([[[-103.0, 36.5], [-103.0, 33.0], [-94.0, 33.0], [-94.0, 36.5], [-103.0, 36.5]]]);

    const start0 = ee.Date('2007-08-10');
    const end0   = ee.Date('2007-08-21'); // exclusive (covers Aug 10-20)
    let start = start0;
    let end   = end0;

    // 2. Data Acquisition & Check
    let col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY').filterDate(start, end);
    let nImg = await getInfo(col.size());
    if (nImg === 0) {
      // Recovery: widen date window by +/- 3 days
      start = start0.advance(-3, 'day');
      end   = end0.advance(3, 'day');
      col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY').filterDate(start, end);
      nImg = await getInfo(col.size());
      if (nImg === 0) {
        console.log(`Dataset: CHIRPS DAILY, Images: 0`);
        console.log('C1: Empty Collection (No images found in date/location).');
        console.log('C1: Empty Collection');
        return;
      }
    }

    // Restrict to the original target window after recovery (if widened) for fairness
    const colTarget = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY').filterDate(start0, end0);
    const nImgTarget = await getInfo(colTarget.size());
    if (nImgTarget === 0) {
      // If original window truly has zero, still report C1
      console.log(`Dataset: CHIRPS DAILY, Images: 0 (target window)`);
      console.log('C1: Empty Collection (No images found in date/location).');
      console.log('C1: Empty Collection');
      return;
    }

    // 3. Processing
    const sumImg = colTarget.sum().rename('precip'); // mm over window

    // Pixel count to detect C2
    const scale = 10000;
    const countOK = await getInfo(sumImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: centralOK,
      scale: scale,
      maxPixels: 1e10
    }).get('precip'));
    const countTX = await getInfo(sumImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: northTX,
      scale: scale,
      maxPixels: 1e10
    }).get('precip'));
    if (!countOK || !countTX || countOK === 0 || countTX === 0) {
      console.log(`Dataset: CHIRPS DAILY, Date: 2007-08-10 to 2007-08-20`);
      console.log(`Images: ${nImgTarget}`);
      console.log(`Central OK Pixels: ${countOK || 0}, North TX Pixels: ${countTX || 0}`);
      console.log('C2: No Valid Pixels');
      return;
    }

    // 4. Calculation
    const meanOK = await getInfo(sumImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: centralOK,
      scale: scale,
      maxPixels: 1e10
    }).get('precip'));
    const meanTX = await getInfo(sumImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: northTX,
      scale: scale,
      maxPixels: 1e10
    }).get('precip'));

    // 5. Validation & Final Answer
    const invalid = (v) => v === null || v === undefined || !isFinite(v) || v < 0 || v > 2000;
    if (invalid(meanOK) || invalid(meanTX)) {
      console.log(`Dataset: CHIRPS DAILY, Date: 2007-08-10 to 2007-08-20`);
      console.log(`Images: ${nImgTarget}`);
      console.log(`Check: meanOK=${meanOK}, meanTX=${meanTX}`);
      console.log('C3: Calculation Failure');
      return;
    }

    const diff = meanOK - meanTX;
    const fmt = (x) => (Math.round(x * 100) / 100).toFixed(2);

    console.log(`Dataset: CHIRPS DAILY, Date: 2007-08-10 to 2007-08-20`);
    console.log(`Images: ${nImgTarget}`);
    console.log(`Central OK: Pixels=${countOK}, Mean(mm)=${fmt(meanOK)}`);
    console.log(`North TX:   Pixels=${countTX}, Mean(mm)=${fmt(meanTX)}`);
    console.log(`Difference (OK - N TX): ${fmt(diff)} mm`);

    if (diff > 0) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }

  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
